INSERT OR REPLACE INTO firestore_documents (collection_name, document_id, data) VALUES ('feedback', 'GyMdBE4aA1vmRQO8zixQ', '{"userId":"bRpKwXMuelYjNgGOqpEm55PvPTP2","title":"طلب وتوزيع + استلام workflow promt","description":"1. إنشاء MR+MIV (طلب مع خطة توزيع) \n   ↓\n2. الموافقة على الطلب\n   ↓  \n3. استلام المواد MRV (من المورد)\n   ↓\n4. توزيع تلقائي للمساكن حسب خطة MR\n\nالمطلوب تنفيذه:\n1. تعديل صفحة New Order الحالية\nإضافة قسم \"Distribution Plan\" بعد قائمة الأصناف\nالسماح بتحديد وضع التوزيع: Single Residence أو Multiple Residences\nلكل صنف، إمكانية تحديد:\nالمسكن المستهدف\nالكمية\nالموقع (غرفة، حمام، مطبخ - اختياري)\nالتحقق من أن مجموع التوزيع = إجمالي الكمية المطلوبة\n\n3. إنشاء صفحة استلام المواد\nصفحة جديدة: /inventory/receive/[orderId]\n\nجدول لإدخال الكميات المستلمة لكل صنف\nحقول إضافية: المورد، رقم الفاتورة، ملاحظات\nعرض خطة التوزيع المخططة\nزر \"Receive & Auto-Distribute\"\n4. منطق التوزيع التلقائي\nعند الضغط على \"Receive & Auto-Distribute\":\n\nتحديث المخزون العام (+الكمية المستلمة)\nتوزيع نسبي للمساكن حسب الخطة المحددة\nتحديث مخزون كل مسكن\nإنشاء سجلات Distribution\nتحديث حالة الطلب إلى \"Distributed\"\n5. الشروط والتحقق\nمنع التوزيع إذا تم تركيب نفس المادة في نفس المسكن خلال المدة المحددة\nإضافة إعدادات لكل صنف: minimumDaysBetweenInstallations\nعرض تحذير عند محاولة الطلب للمساكن المحظورة\nالملفات المطلوب تعديلها:\npage.tsx - إضافة Distribution Plan\nsrc/types/orders.ts - تحديث الأنواع\norders-context.tsx - إضافة functions للاستلام والتوزيع\nإنشاء page.tsx\nإنشاء src/types/distribution.ts للأنواع الجديدة\nمتطلبات التصميم:\nاستخدام نفس الـ UI components الموجودة (Card, Table, Select, etc.)\nتصميم responsive يتناسب مع الشاشات المختلفة\nرسائل تحذير واضحة للمستخدم\nحفظ تلقائي للمسودة (Draft) كما في الصفحة الحالية\nملاحظات مهمة:\nالحفاظ على جميع الوظائف الحالية للصفحة\nضمان التوافق مع الـ contexts الموجودة\nإضافة validation مناسب\nدعم اللغتين العربية والإنجليزية","category":"Feature Request","deviceInfo":{"userAgent":"Mozilla/5.0 (Windows NT 10.0; Win6